<script setup>
import { computed, ref, shallowRef } from 'vue'
import { mergeCsvGeoJson, parseCsv, parseGeoJson } from './csvGeoJsonMerger.js'
import { downloadFile } from '../shared/download.js'

const csv = shallowRef(null)
const geoJson = shallowRef(null)
const csvColumn = ref(null)
const geoJsonProperty = ref(null)
const csvError = ref('')
const geoJsonError = ref('')
const exportError = ref('')
const loadingCsv = ref(false)
const loadingGeoJson = ref(false)
const exporting = ref(false)
const result = ref(null)

const busy = computed(() => loadingCsv.value || loadingGeoJson.value || exporting.value)
const csvColumns = computed(() => csv.value?.headers.map((title, value) => ({ title, value })) ?? [])
const geoJsonProperties = computed(() =>
  [...new Set(geoJson.value?.features.flatMap((feature) => Object.keys(feature.properties ?? {})))].sort(),
)
const canExport = computed(
  () => csv.value && geoJson.value && Number.isInteger(csvColumn.value) && geoJsonProperty.value !== null,
)

function clearResult() {
  result.value = null
  exportError.value = ''
}

async function loadCsv(file) {
  clearResult()
  csv.value = null
  csvColumn.value = null
  csvError.value = ''
  const selectedFile = Array.isArray(file) ? file[0] : file
  if (!selectedFile) return
  loadingCsv.value = true
  try {
    csv.value = await parseCsv(await selectedFile.text())
  } catch (error) {
    csvError.value = `Could not read CSV: ${error.message}`
  } finally {
    loadingCsv.value = false
  }
}

async function loadGeoJson(file) {
  clearResult()
  geoJson.value = null
  geoJsonProperty.value = null
  geoJsonError.value = ''
  const selectedFile = Array.isArray(file) ? file[0] : file
  if (!selectedFile) return
  loadingGeoJson.value = true
  try {
    geoJson.value = parseGeoJson(await selectedFile.text())
  } catch (error) {
    geoJsonError.value = `Could not read GeoJSON: ${error.message}`
  } finally {
    loadingGeoJson.value = false
  }
}

async function exportGeoJson() {
  if (!canExport.value || busy.value) return
  clearResult()
  exporting.value = true
  // Allow Vue to update the loading state before the synchronous join.
  await new Promise((resolve) => setTimeout(resolve, 0))
  try {
    const output = mergeCsvGeoJson(csv.value, geoJson.value, csvColumn.value, geoJsonProperty.value)
    downloadFile(JSON.stringify(output.collection), 'Combined_geojson_csv_file.geojson')
    result.value = { matchedRows: output.matchedRows, features: output.collection.features.length }
  } catch (error) {
    exportError.value = `Could not export GeoJSON: ${error.message}`
  } finally {
    exporting.value = false
  }
}
const fileUpload = ref()
const secondFileUpload = ref()
</script>

<template>
  <!-- Bố cục: Form hai cột nhận CSV và GeoJSON, chọn khóa nối và xuất dữ liệu kết hợp; mỗi nguồn có trạng thái đọc/lỗi riêng. -->
  <section>
    <h1 class="page-title">Merge CSV + GeoJSON</h1>
    <VaCard>
      <VaCardContent>
        <!-- Đầu vào và cấu hình xuất dùng control Vuestic; submit gọi hàm xử lý của trang, busy khóa thao tác khi đang chạy. -->
        <VaForm novalidate class="space-y-4" @submit.prevent="exportGeoJson">
          <div class="grid gap-6 md:grid-cols-2">
            <div class="space-y-4">
              <VaFileUpload
                id="merger-csv"
                v-model="fileUpload"
                type="single"
                upload-button-text="CSV file"
                file-types=".csv,text/csv"
                :disabled="busy"
                @update:modelValue="loadCsv"
              />
              <VaProgressBar v-if="loadingCsv" indeterminate aria-label="Reading file" />
              <!-- Thông báo đọc/xuất dữ liệu nằm gần thao tác liên quan; điều kiện v-if quyết định lúc hiển thị. -->
              <VaAlert v-if="csvError" color="danger" role="alert">{{ csvError }}</VaAlert>
              <VaSelect
                id="merger-csv-column"
                v-model="csvColumn"
                text-by="title"
                value-by="value"
                label="CSV column to match"
                aria-label="CSV column to match"
                :options="csvColumns"
                :disabled="busy || !csv"
                @update:modelValue="clearResult"
              />
              <p v-if="csv" class="text-sm text-secondary" data-testid="csv-summary">
                {{ csv.rows.length }} CSV rows · {{ csv.headers.length }} columns
              </p>
            </div>

            <div class="space-y-4">
              <VaFileUpload
                id="merger-geojson"
                v-model="secondFileUpload"
                type="single"
                upload-button-text="GeoJSON file"
                file-types=".geojson,.json,application/geo+json,application/json"
                :disabled="busy"
                @update:modelValue="loadGeoJson"
              />
              <VaProgressBar v-if="loadingGeoJson" indeterminate aria-label="Reading file" />
              <VaAlert v-if="geoJsonError" color="danger" role="alert">{{ geoJsonError }}</VaAlert>
              <VaSelect
                id="merger-geojson-property"
                v-model="geoJsonProperty"
                text-by="title"
                value-by="value"
                label="GeoJSON property to match"
                aria-label="GeoJSON property to match"
                :options="geoJsonProperties"
                :disabled="busy || !geoJson || !geoJsonProperties.length"
                @update:modelValue="clearResult"
              />
              <p v-if="geoJson" class="text-sm text-secondary" data-testid="geojson-summary">
                {{ geoJson.features.length }} GeoJSON features
              </p>
              <p v-if="geoJson && !geoJsonProperties.length" role="status">
                No properties are available to match. Choose another GeoJSON file.
              </p>
            </div>
          </div>

          <VaButton type="submit" color="primary" :loading="exporting" :disabled="!canExport || busy">
            Export enriched GeoJSON
          </VaButton>
        </VaForm>

        <VaAlert v-if="exportError" color="danger" class="mt-4" role="alert">
          {{ exportError }}
        </VaAlert>
        <VaAlert
          v-if="result"
          :color="result.features ? 'success' : 'warning'"
          class="mt-4"
          role="status"
          data-testid="merge-result"
        >
          {{ result.matchedRows }} of {{ csv.rows.length }} CSV rows matched {{ result.features }} of
          {{ geoJson.features.length }} GeoJSON features.
          <span v-if="!result.features">The exported FeatureCollection is empty.</span>
          <span v-else>Downloaded: Combined_geojson_csv_file.geojson.</span>
        </VaAlert>
      </VaCardContent>
    </VaCard>
  </section>
</template>
